mapper.select:
SELECT  FROM public.nw_usage_events WHERE tenant_id=#{tenantId} AND invocation_id=#{invocationId}
 AND event_type IN ('media.image','media.video','media.transcription','media.speech')
 AND usage_event_kind='usage_report' AND report_revision=0

SELECT id,tenant_id,event_id,event_type,provider,model,occurred_at,created_at,request_id,root_input_id,session_id,run_id,invocation_id,attempt_id,call_point,tokens,prompt_tokens,completion_tokens,cached_input_tokens,cache_write_input_tokens,reasoning_output_tokens,usage_source,total_amount_cents,currency,meta,pricing_model_id,pricing_model_revision,image_count,video_count,characters,duration_seconds FROM nw_usage_events WHERE tenant_id=#{tenantId} AND root_input_id=#{rootInputId}
AND usage_event_kind='measured' AND event_type NOT IN ('llm.chat','media.image','media.video','media.transcription','media.speech')
UNION ALL SELECT id,tenant_id,event_id,event_type,provider,model,occurred_at,created_at,request_id,root_input_id,session_id,run_id,invocation_id,attempt_id,call_point,tokens,prompt_tokens,completion_tokens,cached_input_tokens,cache_write_input_tokens,reasoning_output_tokens,usage_source,total_amount_cents,currency,meta,NULL::bigint AS pricing_model_id,NULL::bigint AS pricing_model_revision,NULL::bigint AS image_count,NULL::bigint AS video_count,NULL::bigint AS characters,NULL::numeric AS duration_seconds FROM observation_effective_model_usage
WHERE tenant_id=#{tenantId} AND root_input_id=#{rootInputId}
UNION ALL SELECT id,tenant_id,event_id,event_type,provider,model,occurred_at,created_at,request_id,root_input_id,session_id,run_id,invocation_id,attempt_id,call_point,tokens,prompt_tokens,completion_tokens,cached_input_tokens,cache_write_input_tokens,reasoning_output_tokens,usage_source,total_amount_cents,currency,meta,pricing_model_id,pricing_model_revision,image_count,video_count,characters,duration_seconds FROM nw_observation_effective_media_usage
WHERE tenant_id=#{tenantId} AND root_input_id=#{rootInputId} ORDER BY occurred_at,id

SELECT id,tenant_id,event_id,event_type,provider,model,occurred_at,created_at,request_id,root_input_id,session_id,run_id,invocation_id,attempt_id,call_point,tokens,prompt_tokens,completion_tokens,cached_input_tokens,cache_write_input_tokens,reasoning_output_tokens,usage_source,total_amount_cents,currency,meta,pricing_model_id,pricing_model_revision,image_count,video_count,characters,duration_seconds
FROM nw_usage_events WHERE tenant_id=#{tenantId} AND session_id=#{sessionId}
AND usage_event_kind='measured' AND event_type NOT IN ('llm.chat','media.image','media.video','media.transcription','media.speech')
UNION ALL
SELECT id,tenant_id,event_id,event_type,provider,model,occurred_at,created_at,request_id,root_input_id,session_id,run_id,invocation_id,attempt_id,call_point,tokens,prompt_tokens,completion_tokens,cached_input_tokens,cache_write_input_tokens,reasoning_output_tokens,usage_source,total_amount_cents,currency,meta,NULL::bigint AS pricing_model_id,NULL::bigint AS pricing_model_revision,NULL::bigint AS image_count,NULL::bigint AS video_count,NULL::bigint AS characters,NULL::numeric AS duration_seconds
FROM observation_effective_model_usage
WHERE tenant_id=#{tenantId} AND session_id=#{sessionId}
UNION ALL SELECT id,tenant_id,event_id,event_type,provider,model,occurred_at,created_at,request_id,root_input_id,session_id,run_id,invocation_id,attempt_id,call_point,tokens,prompt_tokens,completion_tokens,cached_input_tokens,cache_write_input_tokens,reasoning_output_tokens,usage_source,total_amount_cents,currency,meta,pricing_model_id,pricing_model_revision,image_count,video_count,characters,duration_seconds FROM nw_observation_effective_media_usage
WHERE tenant_id=#{tenantId} AND session_id=#{sessionId}
ORDER BY occurred_at,id
